typedef struct {
    s32 clip_volume;                  /* 0x00: clip volume the hero must enter; -1 = none */
    s32 path_index;                   /* 0x04: row of D_L16_001B0C30; -1 = none */
    f32 speed;                        /* 0x08 */
    f32 step;                         /* 0x0C: progress added each frame */
    union { f32 f; s32 i; } progress; /* 0x10: written as a float, zeroed as an int */
    s16 sound;                        /* 0x14: voice handle */
    s16 triggered;                    /* 0x16: set once the hero is close */
} RocketPathData;

enum GrindrailTriggerState {
    GRINDRAIL_TRIGGER_INITIALIZE = 0,
    GRINDRAIL_TRIGGER_CHECK_LOCAL_BOUNDS = 1,
    GRINDRAIL_TRIGGER_WAIT_FOR_COMMAND_TIMEOUT = 2
};

/* Rocket update: wait for the hero in its clip volume, fly the path once, then hide and reset. */
void update_path_following_rocket(unsigned char *moby) {
    struct Moby *m = (struct Moby *)moby;
    RocketPathData *data = (RocketPathData *)m->pvars;
    char *path = kalebo3_path_table[data->path_index];
    switch (m->state) {
    case 0:
        if (data->clip_volume == -1 || data->path_index == -1) {
            DeleteMoby(m);
            break;
        }
        data->step = data->speed * g_frame_time / FastVecDist(path + 0x10, path + 0x20);
        m->state = 1;
        m->update_dist = 100;
        m->command = 0;
        break;
    case 1: {
        struct Hero *player = (struct Hero *)(hero_globals_base + 0xE1D);
        if (player->state.control_mode != 15)
            break;
        if (is_point_inside_clip_volume(&player->motion.body_center, data->clip_volume)) {
            m->state = 2;
            data->triggered = 0;
        }
        break;
    }
    case 2:
        data->progress.f += data->step;
        if ((float)(*(int *)path - 1) <= data->progress.f) {
            m->update_dist = 0xFF;
            m->state = 3;
        } else {
            SamplePathAt((int *)path, 0, &m->pos, &m->rot.x, 0, data->progress.f);
        }
        if (m->command)
            m->collision = 0;
        if (!Sound_IsPlaying(m, data->sound)) {
            data->sound = Moby_PlaySound_i(0, 4, m);
        }
        if (data->triggered == 0 &&
            vec_distance_xy(&m->pos, &((struct Hero *)(hero_globals_base + 0xE1D))->motion.pos) < 7.0f) {
            data->triggered = 1;
            Moby_PlaySound(1, 0, m);
        }
        break;
    case 3:
        if (m->visible == 0) {
            m->visible = 0;
            m->collision = 0;
            m->flags |= 1;
        }
        if (((struct Hero *)(hero_globals_base + 0xE1D))->state.control_mode != 15) {
            float pos[4];
            qcopy(pos, path + 0x10);
            pos[3] = 3.0f;
            if (FastBSphereCheck((char *)pos, 64.0f) == -1) {
                m->command = 0;
                data->progress.i = 0;
                SamplePathAt((int *)path, 0, &m->pos, &m->rot.x, 0, data->progress.f);
                m->visible = 1;
                m->flags &= ~1;
                m->collision = m->pclass->collision;
                data->triggered = 0;
                m->state = 1;
            }
        }
        break;
    }
}
