/* Update a thrown bomb (class 0x119): fly and bounce off what it hits and off the ground, rest, then burst. */
void update_thrown_bomb(L16FallingMoby *m) {
    float previous[4], normal[4];
    L16FallingData *d = m->data;

    switch (m->state) {
    case 1:
        /* No pointer locals: m->position and d->velocity are written at each use and the compiler caches
           them itself (velocity formed in the argument register and copied to a saved one, the position
           copied a second time for the ground test). */
        qcopy(previous, m->position);
        FastVecAdd(m->position, m->position, d->velocity);
        if (coll_line_spark(previous, m->position, 5, d->owner, 0)) {
            vec_scale_to_length(normal, kalebo3_coll_hit_hit.normal, 1.0f);
            if (FastVecDot(normal, d->velocity) < 0.0f) {
                vec_reflect(d->velocity, d->velocity, normal);
                FastVecScale(d->velocity, d->velocity, 0.25f);
            }
        }
        if (coll_sphere(0.333f, m->position, 2, 0)) {
            vec_scale_to_length(normal, kalebo3_coll_hit_hit.normal, 0.333f);
            if (FastVecDot(normal, d->velocity) < 0.0f) {
                vec_reflect(d->velocity, d->velocity, normal);
                FastVecScale(d->velocity, d->velocity, 0.25f);
            }
            qcopy(m->position, kalebo3_coll_hit_hit.position);
            m->position[2] += normal[2];
            if (normal[2] >= 0.3f && FastVecLength(d->velocity) < g_frame_time * 0.25f) {
                m->state = 2;
                d->timer = scale_ticks(90);
            }
        }
        if (fast_dec_timer(&d->timer)) {
            m->state = 3;
        } else if (d->timer < scale_ticks(45) && d->timer % scale_ticks(10) == 0) {
            d->reaction = 250;
            RerollEffectCounter(m, (short *)d);
        }
        d->velocity[2] -= d->gravity;
        break;
    case 2:
        if (fast_dec_timer(&d->timer)) {
            m->state = 3;
        } else if (d->timer < scale_ticks(61) && d->timer % scale_ticks(20) == 0) {
            d->reaction = 250;
            RerollEffectCounter(m, (short *)d);
        }
        break;
    case 3:
        Moby_PlaySound_i(0, 0, m);
        spawn_explosion(m, kalebo3_zero_vec_spark, 0, 1.5f, 1.0f, 7, 10, 20, 3.0f, 1.7f, 4.0f, -1, 1.0f, 7.0f,
                          0, 7, -1, 0);
        DeleteMoby(m);
        return;
    }
    StepColorFade(m, d);
}
