/* Updates the test dummy (moby class 541): walks its path, throws at or sprays its target, bursts and respawns. */
/* Updates the test dummy (moby class 541): walks its path, throws at or sprays its target, bursts and respawns. */

void test_dummy_update(unsigned char *moby) {
    enum {
        TEST_DUMMY_STATE_INITIALIZE = 0,
        TEST_DUMMY_STATE_IDLE = 1,
        TEST_DUMMY_STATE_APPROACH_FIRST_PATH_NODE = 2,
        TEST_DUMMY_STATE_APPROACH_THROW_NODE = 3,
        TEST_DUMMY_STATE_THROW_AT_TARGET = 4,
        TEST_DUMMY_STATE_MOVE_ALONG_PATH = 5,
        TEST_DUMMY_STATE_TURN_TO_NEXT_PATH_NODE = 6,
        TEST_DUMMY_STATE_APPROACH_SPRAY_NODE = 7,
        TEST_DUMMY_STATE_SPRAY_FROM_CHILD = 8,
        TEST_DUMMY_STATE_TURN_AND_RESUME_SAVED_STATE = 9,
        TEST_DUMMY_STATE_BURST = 10,
        TEST_DUMMY_STATE_RESPAWN = 11
    };
    enum {
        TEST_DUMMY_KIND_THROWER = 0,
        TEST_DUMMY_KIND_PATH_MOVER = 1,
        TEST_DUMMY_KIND_SPRAYER = 2
    };
    L16SparkVector position_or_delta, position_or_direction, launch_velocity;
    L16SparkQuery fx;
    L16DummyData *dummy_data = (L16DummyData *)((struct Moby *)moby)->pvars;
    /* A count, then 16-byte points from +0x10. A point copied whole is `path + i * 16 + 16`; its x and y are read
       through `path + (i << 4)`: retail forms index + base for the first and base + index for the second, which
       is what this compiler does with a multiplication and with a shift in an address. */
    char *path;

    update_test_dummy_damage_and_respawn(moby);
    path = kalebo3_path_table[dummy_data->path];
    Manipulator_ApplyScale(2.5f, (int)moby, 2, (unsigned char *)dummy_data->block140);
    switch (((struct Moby *)moby)->state) {
    case TEST_DUMMY_STATE_INITIALIZE: /* set up: lives, home position, the held child for the variant */
        dummy_data->b2E = 1;
        if (dummy_data->lives > 0) {
            *(short *)(moby + 0xB4) /= dummy_data->lives;
        }
        ((struct Moby *)moby)->state = TEST_DUMMY_STATE_IDLE;
        ((struct Moby *)moby)->visible = 0;
        ((struct Moby *)moby)->flags |= 1;
        if (random_integer_below(2)) {
            ((struct Moby *)moby)->flags |= 0x8000;
        }
        dummy_data->b28 = 1;
        dummy_data->h24 = 2;
        dummy_data->f20 = 2.0f;
        dummy_data->f11C = random_angle_radians();
        dummy_data->route = find_nearest_test_dummy_door(dummy_data->iCC, &((struct Moby *)moby)->pos);
        qcopy(dummy_data->spawn, &((struct Moby *)moby)->pos);
        switch (dummy_data->kind) {
        case TEST_DUMMY_KIND_THROWER:
            dummy_data->child = CreateMoby_m(0x35F);
            break;
        case TEST_DUMMY_KIND_PATH_MOVER:
            dummy_data->child = CreateMoby_m(0x374);
            break;
        case TEST_DUMMY_KIND_SPRAYER:
            dummy_data->child = CreateMoby_m(0x36C);
            reset_shot_tracking(dummy_data->slots);
            break;
        }
        if (dummy_data->child) {
            ((struct Moby *)dummy_data->child)->flags |= 0x100;
            *(short *)(dummy_data->child + 0x32) = 0x40;
            *(unsigned char *)(dummy_data->child + 0x30) = 0;
            ((struct Moby *)dummy_data->child)->visible = 1;
        }
        break;
    case TEST_DUMMY_STATE_IDLE:
        break;
    case TEST_DUMMY_STATE_APPROACH_FIRST_PATH_NODE: /* turn to the path's first node, then start by variant */
        refresh_test_dummy_door_timer(dummy_data->route);
        position_or_delta.quad = *(u128 *)(path + 0x10);
        if (move_test_dummy_toward_position_and_heading(moby, position_or_delta.f, ((struct Moby *)moby)->rot.z)) {
            dummy_data->timer = scale_ticks(30);
            dummy_data->node = 1;
            dummy_data->step = 1;
            if (dummy_data->kind == TEST_DUMMY_KIND_THROWER) {
                ((struct Moby *)moby)->state = TEST_DUMMY_STATE_APPROACH_THROW_NODE;
            } else if (dummy_data->kind == TEST_DUMMY_KIND_PATH_MOVER) {
                ((struct Moby *)moby)->state = TEST_DUMMY_STATE_MOVE_ALONG_PATH;
            } else {
                ((struct Moby *)moby)->state = TEST_DUMMY_STATE_APPROACH_SPRAY_NODE;
            }
        }
        break;
    case TEST_DUMMY_STATE_APPROACH_THROW_NODE: /* thrower: wait, face the node, wind up */
        if (fast_dec_timer(&dummy_data->timer)) {
            position_or_delta.quad = *(u128 *)(path + dummy_data->node * 16 + 16);
            if (move_test_dummy_toward_position_and_heading(moby, position_or_delta.f, fast_atan2(
                    ((float *)(path + (dummy_data->node << 4)))[4] - ((struct Moby *)moby)->pos.x,
                    ((float *)(path + (dummy_data->node << 4)))[5] - ((struct Moby *)moby)->pos.y))) {
                dummy_data->timer = scale_ticks(30);
                ((struct Moby *)moby)->state = TEST_DUMMY_STATE_THROW_AT_TARGET;
                if (((struct Moby *)moby)->prev_seq != 21) {
                    MobyBlendAnimation(moby, 21, 0, scale_ticks(30));
                }
                if (random_integer_below(2)) {
                    char *p = kalebo3_path_table[dummy_data->sound_path];
                    FindNearestEligibleMoby(moby, dummy_data->target, 12.0f, 0, 0, p + 16, *(int *)p);
                } else {
                    dummy_data->mode = 2;
                }
            }
        }
        break;
    case TEST_DUMMY_STATE_THROW_AT_TARGET: /* thrower: launch the held object at the target, then face it or the next node */
        if (dummy_data->mode == 2) {
            qcopy(position_or_delta.f, kalebo3_level_cuboids_m + dummy_data->aim[dummy_data->node] * 0x80 + 0x30);
        } else {
            qcopy(position_or_delta.f, dummy_data->target);
        }
        if (IsFrameWithinWindow(moby, 15.0f) && dummy_data->child) {
            float speed = test_dummy_bomb_horizontal_launch_speed * g_frame_time;
            float gravity = g_frame_time_sq * 10.0f;
            position_or_delta.f[2] = ProbeGroundHeight(position_or_delta.f, 0, 0.5f);
            Moby_GetJointWorldPos(dummy_data->child, 0, position_or_direction.f);
            FastVecSub(launch_velocity.f, position_or_delta.f, position_or_direction.f);
            launch_velocity.f[2] = 0.0f;
            vec_scale_to_length(launch_velocity.f, launch_velocity.f, speed);
            launch_velocity.f[2] = jump_speed_4318(position_or_direction.f, position_or_delta.f, 0, speed, -gravity);
            spawn_thrown_bomb_r((int)moby, position_or_direction.f, launch_velocity.f, gravity, scale_ticks(300));
        } else if (((struct Moby *)moby)->anim_flags & 2) {
            dummy_data->node = (dummy_data->node + 1) & 1;
            ((struct Moby *)moby)->state = TEST_DUMMY_STATE_APPROACH_THROW_NODE;
            if (((struct Moby *)moby)->prev_seq != 23) {
                MobyBlendAnimation(moby, 23, 0, scale_ticks(30));
            }
        }
        if (MobyGetFrameValue(moby) < 15.0f) {
            position_or_direction.quad = *(u128 *)&((struct Moby *)moby)->pos;
            move_test_dummy_toward_position_and_heading(moby, position_or_direction.f, fast_atan2(
                position_or_delta.f[0] - ((struct Moby *)moby)->pos.x,
                position_or_delta.f[1] - ((struct Moby *)moby)->pos.y));
        } else {
            int node = (dummy_data->node + 1) & 1;
            position_or_direction.quad = *(u128 *)&((struct Moby *)moby)->pos;
            move_test_dummy_toward_position_and_heading(moby, position_or_direction.f, fast_atan2(
                ((float *)(path + (node << 4)))[4] - ((struct Moby *)moby)->pos.x,
                ((float *)(path + (node << 4)))[5] - ((struct Moby *)moby)->pos.y));
        }
        break;
    case TEST_DUMMY_STATE_MOVE_ALONG_PATH: /* slider: move toward the node, emit, stop on arrival */
        if (((struct Moby *)moby)->prev_seq == 10) {
            if (((struct Moby *)moby)->anim_flags & 2) {
                MobyBlendAnimation(moby, 11, 0, 1);
            }
        } else {
            char *position = (char *)&((struct Moby *)moby)->pos;
            char *g;
            FastVecSub(position_or_delta.f, path + (dummy_data->node * 16 + 16), position);
            ClampVectorLength(position_or_delta.f, test_dummy_move_step_limit * g_frame_time);
            FastVecAdd(position, position, position_or_delta.f);
            Moby_GetJointWorldPos(moby, test_dummy_hold_joint, position_or_direction.f);
            MobySphereHitDirectional_r((int)moby, 0.333f, position_or_direction.f, 1, 1.0f, 1.0f, 0, 1, 0);
            g = hero_globals_base + 0xE1D;
            if (kalebo3_coll_hit_moby == *(char **)(g + 0x2080) && *(int *)(g + 0x1C0) == 0) {
                Moby_PlaySound_i(6, 0, moby);
            }
            if (FastVecLength(position_or_delta.f) < 0.0001f) {
                if (((struct Moby *)moby)->prev_seq != 9) {
                    MobyBlendAnimation(moby, 9, 0, scale_ticks(20));
                }
                ((struct Moby *)moby)->state = TEST_DUMMY_STATE_TURN_TO_NEXT_PATH_NODE;
                dummy_data->timer = scale_ticks(60);
                if (dummy_data->node == 0) {
                    dummy_data->step = 1;
                } else if (dummy_data->node == *(int *)path - 1) {
                    dummy_data->step = -1;
                }
            }
        }
        break;
    case TEST_DUMMY_STATE_TURN_TO_NEXT_PATH_NODE: { /* slider: turn toward the next node while the timer runs */
        float *yaw = &((struct Moby *)moby)->rot.z;
        int next = dummy_data->node + dummy_data->step;
        float angle = fast_atan2(
            ((float *)(path + (next << 4)))[4] - ((struct Moby *)moby)->pos.x,
            ((float *)(path + (next << 4)))[5] - ((struct Moby *)moby)->pos.y);
        SteerAngleWithVelocity(yaw, &dummy_data->turn, angle, g_frame_time_sq * 12.566371f, g_frame_time_sq * 12.566371f, g_frame_time * 25.132742f);
        if (fast_dec_timer(&dummy_data->timer)) {
            dummy_data->node = next;
            if (((struct Moby *)moby)->prev_seq != 10) {
                MobyBlendAnimation(moby, 10, 0, scale_ticks(10));
            }
            ((struct Moby *)moby)->state = TEST_DUMMY_STATE_MOVE_ALONG_PATH;
        }
        break;
    }
    case TEST_DUMMY_STATE_APPROACH_SPRAY_NODE: /* sprayer: wait, face the node, start */
        if (fast_dec_timer(&dummy_data->timer)) {
            position_or_delta.quad = *(u128 *)(path + dummy_data->node * 16 + 16);
            if (move_test_dummy_toward_position_and_heading(moby, position_or_delta.f, ((struct Moby *)moby)->rot.z)) {
                dummy_data->timer = scale_ticks(30);
                ((struct Moby *)moby)->state = TEST_DUMMY_STATE_SPRAY_FROM_CHILD;
                if (((struct Moby *)moby)->prev_seq != 1) {
                    MobyBlendAnimation(moby, 1, 0, scale_ticks(30));
                }
                if (random_integer_below(2)) {
                    char *p = kalebo3_path_table[dummy_data->sound_path];
                    FindNearestEligibleMoby(moby, dummy_data->target, 12.0f, 0, 0, p + 16, *(int *)p);
                } else {
                    dummy_data->mode = 2;
                }
            }
        }
        break;
    case TEST_DUMMY_STATE_SPRAY_FROM_CHILD: /* sprayer: face the target and emit from the child toward it */
        if (dummy_data->mode != 2) {
            position_or_delta.quad = *(u128 *)&((struct Moby *)moby)->pos;
            move_test_dummy_toward_position_and_heading(moby, position_or_delta.f, fast_atan2(
                dummy_data->target[0] - ((struct Moby *)moby)->pos.x,
                dummy_data->target[1] - ((struct Moby *)moby)->pos.y));
        }
        if (dummy_data->child) {
            char *slots;
            Moby_GetJointWorldPos(dummy_data->child, 0, position_or_delta.f);
            slots = dummy_data->slots;
            position_or_direction.f[0] = FastCos(fast_atan2(
                position_or_delta.f[0] - ((struct Moby *)moby)->pos.x,
                position_or_delta.f[1] - ((struct Moby *)moby)->pos.y));
            position_or_direction.f[1] = FastSin(fast_atan2(
                position_or_delta.f[0] - ((struct Moby *)moby)->pos.x,
                position_or_delta.f[1] - ((struct Moby *)moby)->pos.y));
            position_or_direction.f[2] = 0.0f;
            effect_slots_fire(slots, position_or_delta.f, position_or_direction.f, test_dummy_shot_distance);
            position_or_direction.f[3] = 5627.925f;
            position_or_direction.f[2] = 1.0f;
            InitDirectionalHitQuery(&fx, moby, 0x10001, 1.0f, position_or_direction.f);
            fx.kind = 5;
            fx.enabled = 1;
            fx.cls = *(unsigned short *)(moby + 0xA6);
            collect_mobies_around_tracked_objects((char **)slots, (int)moby, (int)&fx);
        }
        if (((struct Moby *)moby)->anim_flags & 2) {
            dummy_data->node = (dummy_data->node + 1) & 1;
            ((struct Moby *)moby)->state = TEST_DUMMY_STATE_APPROACH_SPRAY_NODE;
            if (((struct Moby *)moby)->prev_seq != 3) {
                MobyBlendAnimation(moby, 3, 0, scale_ticks(30));
            }
        }
        break;
    case TEST_DUMMY_STATE_TURN_AND_RESUME_SAVED_STATE: /* turn back to the node, then resume the saved state and animation */
        position_or_delta.quad = *(u128 *)(path + dummy_data->node * 16 + 16);
        move_test_dummy_toward_position_and_heading(moby, position_or_delta.f, dummy_data->f10C);
        if (((struct Moby *)moby)->anim_flags & 2) {
            ((struct Moby *)moby)->state = dummy_data->next_state;
            if (((struct Moby *)moby)->prev_seq != dummy_data->next_anim) {
                MobyBlendAnimation(moby, dummy_data->next_anim, 0, scale_ticks(20));
            }
        }
        break;
    case TEST_DUMMY_STATE_BURST: { /* burst into three pieces; respawn at home or delete */
        char *position = (char *)&((struct Moby *)moby)->pos;
        char *rot = (char *)&((struct Moby *)moby)->rot;
        float burst;
        dummy_data->f20 = 2.0f;
        dummy_data->timer = scale_ticks(60);
        burst = g_frame_time_sq * 12.0f;
        SpawnBreakFragment(moby, 0x655, position, rot, 0, 0, burst, kalebo3_zero_vec_spark, kalebo3_zero_vec_spark, kalebo3_zero_vec_spark);
        SpawnBreakFragment(moby, 0x656, position, rot, 0, 0, burst, kalebo3_zero_vec_spark, kalebo3_zero_vec_spark, kalebo3_zero_vec_spark);
        SpawnBreakFragment(moby, 0x657, position, rot, 0, 0, burst, kalebo3_zero_vec_spark, kalebo3_zero_vec_spark, kalebo3_zero_vec_spark);
        qcopy(position_or_delta.f, position);
        position_or_delta.f[2] += 1.2f;
        SpawnExplosionFx(moby, position_or_delta.f, -1, 0.5f, 10.0f);
        SetDeathBits(moby, 0, -1);
        Moby_PlaySound_i(7, 0, moby);
        dummy_data->lives--;
        if (dummy_data->lives != -1) {
            ((struct Moby *)moby)->state = TEST_DUMMY_STATE_RESPAWN;
            qcopy(position, dummy_data->spawn);
            dummy_data->timer = scale_ticks(60);
        } else {
            if (dummy_data->child) {
                DeleteMoby(dummy_data->child);
            }
            DeleteMoby(moby);
        }
        break;
    }
    case TEST_DUMMY_STATE_RESPAWN: /* respawn: settle to the home height as the timer runs out */
        if (fast_dec_timer(&dummy_data->timer)) {
            dummy_data->turn = 0.0f;
            ((struct Moby *)moby)->state = TEST_DUMMY_STATE_APPROACH_FIRST_PATH_NODE;
            if (((struct Moby *)moby)->prev_seq != 9) {
                MobyBlendAnimation(moby, 9, 0, scale_ticks(10));
            }
            dummy_data->f20 = 2.0f;
            ((struct Moby *)moby)->flags |= 0x1000;
        }
        ((struct Moby *)moby)->pos.z = dummy_data->spawn[2] + g_frame_time * 3.0f * (float)dummy_data->timer;
        break;
    }
}
