/* The test dummy's respawn and hit handling: respawns or deletes it, takes damage, and carries its child on a joint. */
void update_test_dummy_damage_and_respawn(void *moby) {
    L16HitMoby *m = moby;
    float matrix[16];
    int status;
    float amount;
    L16HitData *d;
    char *record;

    if (m->state == 1) {
        return;
    }
    d = m->data;
    if (d->substate == 2) {
        d->substate = 1;
        d->health = 2.0f;
        d->timer = scale_ticks(60);
        SetDeathBits(m, 0, -1);
        m->flags &= 0xEFFF;
        d->lives--;
        if (d->lives != -1) {
            m->state = 11;
            qcopy(m->position, d->spawn);
            d->timer = scale_ticks(60);
        } else {
            if (d->child) {
                DeleteMoby(d->child);
            }
            DeleteMoby(m);
        }
        return;
    }
    if (d->frame != kalebo3_frame_count) {
        update_test_dummy_group_glow_phases((char *)m);
    }
    amount = 0.0f;
    record = MobyGetHitMessage(m, 0x330000, 0);
    ComputeHitResponse(m, record, &d->health, 0, &status, &amount, 0, 4);
    if (status != 1 && m->state != 10 && m->state != 11) {
        d->health -= amount;
        if (d->health <= 0.0f) {
            m->state = 10;
        } else {
            if (m->state != 9) {
                d->next_state = m->state;
                d->next_anim = m->animation;
            }
            {
                float x = m->position[0], y = m->position[1];
                L16HitPlayer *player = (L16HitPlayer *)(hero_globals_base + 0xE1D);
                d->heading = fast_atan2(player->position[0] - x, player->position[1] - y);
            }
            m->state = 9;
            /* No pointer local for the reaction record anywhere: d->reaction is written at each call and the
               compiler caches it itself (formed before the hit query, and formed again here with a copy after
               the call). It only forms it again here when this place cannot be reached along one straight path
               from the hit query, that is when the animation test has two arms while its common-subexpression
               pass runs: the else arm below is what supplies the second one. The assignment is dead and leaves
               no instruction; without it the function is two instructions short (see NOTES.md). */
            if (m->animation != 8) {
                MobyBlendAnimation(m, 8, 2, 1);
            } else {
                record = 0;
            }
            d->reaction_time = 120;
            RerollEffectCounter(m, d->reaction);
        }
    }
    m->opacity = 255;
    StepColorFade(m, d->reaction);
    if (d->child) {
        Moby_GetJointWorldPos(m, test_dummy_hold_joint, d->child->position);
        MobyTransformScaledVertex((char *)m, test_dummy_hold_joint, (char *)matrix);
        matrix_copy_rows(d->child->matrix[0], matrix);
        vec_scale_to_length(d->child->matrix[0], d->child->matrix[0], 1.0f);
        vec_scale_to_length(d->child->matrix[1], d->child->matrix[1], 1.0f);
        vec_scale_to_length(d->child->matrix[2], d->child->matrix[2], 1.0f);
        moby_build_matrix(d->child);
    }
    StepColorFade(m, d->reaction);
}
