/* Draw callback queued by func_L16_002D0238: one textured quad per live test dummy (class 0x21D) of the
   group, its colour pulsing with the dummy's phase, its frame built from the direction to the target. */
void draw_test_dummy_group_glows(L16BeamMoby *moby) {
    L16RibbonPacket packet;
    float a[4];
    float b[4];
    float c[4];
    float pos[4];
    short *p;
    L16BeamMoby *other;
    L16DummyData *data;
    int k, id, color;
    float wave;
    float blend;

    packet.texture = GetEffectTex(11);
    packet.mode = 0x8000000048L;
    packet.flags = 0xFF9000000260L;
    packet.zero = 5;
    packet.uv[0].u = 0.0f;
    packet.uv[0].v = 0.0f;
    packet.uv[1].u = 0.0f;
    packet.uv[1].v = 1.0f;
    packet.uv[2].u = 1.0f;
    packet.uv[2].v = 0.0f;
    packet.uv[3].u = 1.0f;
    packet.uv[3].v = 1.0f;
    for (k = 0; k < 4; k++) {
        FastVecScale(packet.point[k], test_dummy_glow_quad_points[k], 0.2f);
    }
    p = (short *)kalebo3_moby_groups[moby->group];
    do {
        id = *p & 0x7FFF;
        other = (L16BeamMoby *)(kalebo3_moby_array + (id << 8));
        data = other->data;
        wave = FastSin(data->f11C);
        blend = (wave + 1.0f) * 0.5f;
        color = FastTweenColor_r(test_dummy_glow_pulse_color_start, test_dummy_glow_pulse_color_end, blend);
        packet.color[3] = color;
        packet.color[2] = color;
        packet.color[1] = color;
        packet.color[0] = color;
        if (other && other->type == 0x21D && other->state != 0xFE && other->state != 0xFD) {
            qcopy(pos, other->position);
            pos[2] += 0.2f;
            pos[3] = 1.0f;
            FastVecSub(a, kalebo3_camera_pos, pos);
            vec_scale_to_length(a, a, 1.0f);
            FastVecCross(b, a, hero_globals_base + 0x10AD);
            vec_scale_to_length(b, b, -1.0f);
            FastVecCross(c, b, a);
            draw_world_quad(&packet, a, 0);
        }
    } while (*p++ >= 0);
}
