typedef struct {
    int count;                  /* 0x00: number of nodes */
    char pad04[0xC];
    float points[1][4];         /* 0x10: position; w marks the node */
} L16PatrolPath;

typedef struct {
    char pad0[0x260];
    float position[4];          /* 0x260 */
    char pad270[0x20];
    int base_path;              /* 0x290: index into D_L16_001B0C30 */
    int branch_path[7];         /* 0x294: indexed by a node's mark - 11 */
    char pad2B0[0x10];
    L16PatrolPath *path;        /* 0x2C0: the path being followed */
    char pad2C4[0x30];
    short node;                 /* 0x2F4: the node being steered for */
} L16PatrolData;


/* Choose the path node to steer for: step on while the current one is behind the moby or reached. */
void advance_hoverboard_dummy_path_node(char *m) {
    Moby *moby = (Moby *)m;
    L16PatrolData *d = (L16PatrolData *)moby->pvars;
    float target[4];
    float heading, distance;

    copy_hoverboard_dummy_path_node((Level16VendorVectorMoby *)moby, d->node, target);
    heading = fast_atan2(target[0] - moby->pos.x, target[1] - moby->pos.y);
    for (;;) {
        L16PatrolPath *path;
        L16PatrolPath *base;

        copy_hoverboard_dummy_path_node((Level16VendorVectorMoby *)moby, d->node, target);
        distance = vec_distance_xy(target, d->position);
        if ((FastDiffRots(heading, moby->rot.z) < 1.5707964f || distance > 4.0f) && distance > 2.0f) {
            break;
        }
        path = d->path;
        d->node = (d->node + 1) % path->count;
        base = (L16PatrolPath *)kalebo3_path_table[d->base_path];
        if (path != base) {
            /* At the last node of a branch: back to the base path, five nodes past its nearest one. */
            if (d->node == path->count - 1) {
                d->path = base;
                d->node = select_point_index_by_distance(d->position, base, 0.0f);
                d->node = offset_path_index((char *)d->path, d->node, 5, 1);
            }
        } else if (path->points[d->node][3] > 10.0f && random_integer_below(100) >= 31) {
            /* At a marked node of the base path: more often than not, onto the branch the mark names. */
            int branch = truncate_float_to_s32_r(d->path->points[d->node][3]) - 11;

            d->path = (L16PatrolPath *)kalebo3_path_table[d->branch_path[branch]];
            d->node = 0;
        }
        /* The same two statements as before the loop, written out again: the compiler merges the copies. */
        copy_hoverboard_dummy_path_node((Level16VendorVectorMoby *)moby, d->node, target);
        heading = fast_atan2(target[0] - moby->pos.x, target[1] - moby->pos.y);
    }
}
