        *(int *)&((Moby *)m)->rot.x = 0;
        *(int *)&((Moby *)m)->rot.y = 0;
        ((Moby *)m)->rot.z = fast_atan2(*(float *)(path + 0x20) - *(float *)(path + 0x10),
                                                 *(float *)(path + 0x24) - *(float *)(path + 0x14));
