// State machine for a moby that eases its position toward a target.
void test_dummy_door_update(char *moby) {
    enum {
        TEST_DUMMY_DOOR_STATE_INITIALIZE = 0,
        TEST_DUMMY_DOOR_STATE_UPDATE_HEIGHT = 1
    };
    struct Moby *m = (struct Moby *)moby;
    char *data = (char *)m->pvars;
    switch (m->state) {
    case TEST_DUMMY_DOOR_STATE_INITIALIZE:
        m->state = 1;
        *(float *)data = m->pos.z;
        break;
    case TEST_DUMMY_DOOR_STATE_UPDATE_HEIGHT: {
        int timer_result = fast_dec_timer((int *)(data + 8));
        float target_height;
        if (timer_result != 0) {
            if (timer_result == 2) {
                if (subtract_integer_with_clamp(*(int *)&last_test_dummy_door_sound_request_frame - kalebo3_frame_count) >= 4) {
                    *(int *)&last_test_dummy_door_sound_request_frame = kalebo3_frame_count;
                    Moby_PlaySound(1, 0, moby);
                }
            }
            target_height = *(float *)data;
        } else {
            target_height = *(float *)data + *(float *)&test_dummy_door_height_offset;
        }
        ApproachWithVelocity(target_height, g_frame_time_sq * 10.0f, g_frame_time_sq * 10.0f, g_frame_time * 10.0f,
                             &m->pos.z, (float *)(data + 4));
        break;
    }
    }
}
/* The linked moby of class 0x28A nearest a position, within 37 units. */
void *find_nearest_test_dummy_door(int index, void *position) {
    short *p = (short *)kalebo3_moby_groups[index];
    char *nearest = 0;
    float distance = 37.0f;
    char *moby;
    float d;
    if (!p) return 0;
    while (1) {
        moby = kalebo3_moby_array + ((*(unsigned short *)p & 0x7FFF) << 8);
        if (*(short *)(moby + 0xA6) != 0x28A) continue;
        d = FastVecDist(position, moby + 0x10);
        if (d < distance) {distance = d; nearest = moby;}
        if (*p++ < 0) return nearest;
    }
}
