// Returns 0 if not in state 7/8, 2 if state 8 with data float > 0.2, else 1.
int get_target_reposition_status(char *m) {
    unsigned char s = m[0x20];
    m = ((char *)((Moby *)m)->pvars);
    if (s == 7 || s == 8) {
        if (s == 8 && *(float *)(m + 0x34) > 0.2f) {
            return 2;
        }
        return 1;
    }
    return 0;
}
