/* Update of the crate platform: hit reaction, then its seven states. */
void CratePlatformUpdate(L16CrateMoby *m) {
    L16CrateData *d = m->data;
    char *hit;

    if ((m->status & 2) && m->frame == m->animation && m->frame == 1)
        MobyBlendAnimation(m, 4, 0, scale_ticks(5));
    if (((L16CratePlayer *)(hero_globals_base + 0xE1D))->standing == m && m->animation != 1 && m->frame != 1)
        MobyBlendAnimation(m, 1, 0, scale_ticks(5));
    hit = MobyGetHitMessage(m, 0x210000, 0);
    if (!hit && d->child)
        hit = MobyGetHitMessage(d->child, 0x210000, 0);
    if (hit && m->state != 6) {
        L16CratePlayer *hero = (L16CratePlayer *)(hero_globals_base + 0xE1D);

        d->knock_drag = 0.008f;
        d->knock_gravity = 0.0005f;
        d->knock_speed = g_frame_time * 24.0f;
        d->knock_rise = g_frame_time * 12.0f;
        d->knock_flags = 1;
        d->knock_bAD = 0;
        InitKnockback(m, d->knock, 1, 1, 0,
                          fast_atan2(m->position[0] - hero->position[0], m->position[1] - hero->position[1]));
        d->ticks = 0x78;
        SetDeathBits(m, 0, -1);
        m->state = 6;
    }
    m->opacity = 0xFF;
    switch (m->state) {
    case 0:
        if (d->mode == 2) {
            m->state = 1;
            d->turn = 0.0f;
            MobySetAnimation(m, 4, 0);
        } else {
            if (d->path == -1) {
                STUB_printf(crate_platform_no_path_msg, m->id);
                DeleteMoby(m);
                return;
            }
            if (*(int *)kalebo3_path_table[d->path] == 0) {
                STUB_printf(crate_platform_empty_path_msg, m->id);
                DeleteMoby(m);
                return;
            }
            if (d->mode != 1) {
                if (d->other_path == -1) {
                    STUB_printf(crate_platform_no_other_path_msg, m->id);
                    DeleteMoby(m);
                    return;
                }
                if (*(int *)kalebo3_path_table[d->other_path] == 0) {
                    STUB_printf(crate_platform_empty_other_path_msg, m->id);
                    DeleteMoby(m);
                    return;
                }
            }
            if (d->trigger == -1) {
                STUB_printf(crate_platform_no_trigger_msg, m->id);
                DeleteMoby(m);
                return;
            }
            initialize_moby_path_state(m);
            m->state = 2;
            m->collision = 0x80;
            m->flags |= 0x41;
            m->bounds = 0;
        }
        d->child = 0;
        break;
    case 1: {
        L16CratePlayer *hero = (L16CratePlayer *)(hero_globals_base + 0xE1D);

        MobySpringTurn_path54((char *)m,
                                 fast_atan2(hero->position[0] - m->position[0], hero->position[1] - m->position[1]),
                                 &d->turn, 0.005f, 0.2f, 0.0f);
        emit_moby_offset_particles(m);
        break;
    }
    case 2:
        if (is_point_inside_clip_volume(hero_globals_base + 0xE9D, d->trigger)) {
            if (d->mode == 1) {
                MobySetAnimation(m, 0, 0);
            } else {
                d->child = spawn_floating_mine(m, m->position);
                update_linked_moby_position(m);
                MobySetAnimation(m, 2, 0);
            }
            m->flags &= 0xFFBE;
            m->bounds = m->model->bounds;
            m->state = 4;
        }
        break;
    case 4:
        if (d->mode == 0)
            update_linked_moby_position(m);
        if (advance_bolt_thief_path((char *)m)) {
            m->state = 3;
            MobyBlendAnimation(m, 3, 0, 5);
        }
        emit_moby_offset_particles(m);
        break;
    case 3: {
        L16CrateData *a = m->data;
        char *path = kalebo3_path_table[a->path];
        float target[4];
        float zero;

        if (a->mode == 0)
            update_linked_moby_position(m);
        qcopy(target, path + *(int *)path * 16);
        zero = 0.0f;
        Spring(m->position, &a->vx, target[0], *(float *)&kalebo3_path_spring_stiffness, *(float *)&kalebo3_path_spring_damping, zero);
        Spring(m->position + 1, &a->vy, target[1], *(float *)&kalebo3_path_spring_stiffness, *(float *)&kalebo3_path_spring_damping, zero);
        Spring(m->position + 2, &a->vz, target[2], *(float *)&kalebo3_path_spring_stiffness, *(float *)&kalebo3_path_spring_damping, zero);
        if ((m->status & 2) && m->frame == m->animation) {
            if (a->mode == 1) {
                m->state = 1;
                a->turn = zero;
                MobySetAnimation(m, 4, 0);
            } else {
                if (a->child) {
                    moby_set_state_one(a->child);
                    a->child = 0;
                }
                m->state = 5;
                MobyBlendAnimation(m, 0, 0, 20);
                a->timer = zero;
                a->counter = 0;
            }
        }
        emit_moby_offset_particles(m);
        break;
    }
    case 5:
        if (advance_bolt_thief_path((char *)m)) {
            char *path;

            m->state = 2;
            m->bounds = 0;
            m->flags |= 0x41;
            d->timer = 0.0f;
            d->counter = 0;
            d->turn = d->vx = d->vy = d->vz = d->timer;
            path = kalebo3_path_table[d->path];
            qcopy(m->position, path + 0x10);
            m->rotation[2] = fast_atan2(*(float *)(path + 0x20) - *(float *)(path + 0x10),
                                               *(float *)(path + 0x24) - *(float *)(path + 0x14));
        } else {
            emit_moby_offset_particles(m);
        }
        break;
    case 6:
        if (mine_fall(m, d->knock) & 3) {
            SpawnExplosionFx(m, m->position, -1, 1.0f, 13.0f);
            DeleteMoby(m);
            return;
        }
        if (m->position[2] < 5.0f) {
            DeleteMoby(m);
            return;
        }
        break;
    }
    StepColorFade(m, d->effect);
}
