/* Grind rail button: on a matching side-on hero approach or a hit, fire it; pulse its glow. */
void grindrail_button_update(unsigned char *m) {
    enum {
        GRINDRAIL_BUTTON_INITIALIZE_GLOW_PHASE = 0,
        GRINDRAIL_BUTTON_CHECK_ACTIVATION = 1
    };
    struct Moby *button_moby = (struct Moby *)m;
    char *button_data = (char *)button_moby->pvars;
    char *g;
    char *base;
    float button_offset_from_hero[4];
    float glow_blend_factor;
    switch (button_moby->state) {
    case GRINDRAIL_BUTTON_INITIALIZE_GLOW_PHASE:
        button_moby->state = GRINDRAIL_BUTTON_CHECK_ACTIVATION;
        *(float *)button_data = random_angle_radians();
        break;
    case GRINDRAIL_BUTTON_CHECK_ACTIVATION:
        if (fast_dec_timer((int *)(button_data + 4))) {
            g = hero_globals_base + 0xE9D;
            if (vec_distance_xy(&button_moby->pos, g) < 4.0f) {
                base = g - 0x80;
                if (*(int *)(base + 0x2084) == 0x28 && *(int *)(base + 0x5A8) != -1) {
                    matrix_mul_vec3(button_offset_from_hero, &grindrail_button_local_offset, &button_moby->rot_row0);
                    FastVecAdd(button_offset_from_hero, button_offset_from_hero, &button_moby->pos);
                    FastVecSub(button_offset_from_hero, button_offset_from_hero, g);
                    matrix_mul_vec3(button_offset_from_hero, button_offset_from_hero, g - 0x40);
                    if (FastAbsF(button_offset_from_hero[1]) < 0.1f) {
                        if ((button_offset_from_hero[0] > 0.0f && *(int *)(base + 0x5A8) == 3) ||
                            (button_offset_from_hero[0] < 0.0f && *(int *)(base + 0x5A8) == 2)) {
                            activate_grindrail_button_r(m);
                            Moby_PlaySound_r4(1, 0, m);
                        }
                    }
                }
            }
        }
        if (MobyGetHitMessage(m, 0x330000, 0)) {
            activate_grindrail_button_r(m);
            Moby_PlaySound_r4(0, 0, m);
            button_moby->hit_slot = 0xFF;
        }
        break;
    }
    *(float *)button_data = FastAddRots(*(float *)button_data, g_frame_time * 12.566371f);
    glow_blend_factor = (FastSin(*(float *)button_data) + 1.0f) * 0.5f;
    if (button_moby->command) {
        button_moby->glow_color = FastTweenColor(glow_blend_factor, 0x80208020, 0x80202020);
    } else {
        button_moby->glow_color = FastTweenColor(glow_blend_factor, 0x80202080, 0x80202020);
    }
}
