typedef struct {
    char pad0[0x110];
    short reaction[3];          /* 0x110: record func_L00_0025E4B0 and func_L00_0025E590 take */
    char pad116;
    unsigned char reaction_time; /* 0x117 */
    char pad118[8];
    float knock[4];             /* 0x120: record func_L00_0025D5B0 fills */
    float speed;                /* 0x130 */
    float acceleration;         /* 0x134 */
    float jump_speed;           /* 0x138 */
    float turn_speed;           /* 0x13C */
    int flags;                  /* 0x140 */
    int kind;                   /* 0x144 */
    float strength;             /* 0x148 */
    char pad14C[0x11];
    unsigned char pending;      /* 0x15D */
    char pad15E[0xE];
    float timer;                /* 0x16C */
    float f170;
    float f174;
    char pad178[8];
    float target[4];            /* 0x180 */
    char pad190[0x30];
    int i1C0;
    int i1C4;
    char pad1C8[8];
    float home[4];              /* 0x1D0 */
    char pad1E0[0x10];
    int path;                   /* 0x1F0: index into D_L16_001B0C30 */
} L16PursuitData;
typedef struct {
    char pad0[0x10];
    float position[4];          /* 0x10 */
    unsigned char state;        /* 0x20 */
    char pad21[0x13];
    unsigned short flags;       /* 0x34 */
    char pad36[0x42];
    L16PursuitData *data;       /* 0x78 */
    char pad7C[0x18];
    int i94;
    char pad98[0xC];
    unsigned char bA4;
} L16PursuitMoby;

/* Start the knock-back when the moby is hit, then steer it along its path and note when it strays. */
void update_chomper_hit_reaction_and_target(void *chomper_instance) {
    L16PursuitMoby *chomper_moby = chomper_instance;
    L16PursuitData *pursuit_data = chomper_moby->data;
    char *hit;
    int reaction_kind_or_path_address;          /* the reaction kind, later the path */
    int reaction_flags_or_path_entry_address;   /* the reaction flags, later the path's slot in the table */
    float scratch[8];                           /* [0..3] where the hit came from, [4] the heading that gives */

    if (chomper_moby->state == 0) {
        return;
    }
    hit = MobyGetHitMessage(chomper_moby, 0x330000, 0);
    if (hit) {
        reaction_flags_or_path_entry_address = 0x200;
        pursuit_data->flags = reaction_flags_or_path_entry_address;
        pursuit_data->strength = 0.5f;
        pursuit_data->speed = chomper_knockback_gravity * g_frame_time_sq;
        pursuit_data->acceleration = chomper_knockback_horizontal_speed_approach_rate * g_frame_time_sq;
        pursuit_data->jump_speed = chomper_knockback_horizontal_speed * g_frame_time;
        pursuit_data->turn_speed = chomper_knockback_vertical_speed * g_frame_time;
        reaction_kind_or_path_address = 0x29;
        pursuit_data->kind = reaction_kind_or_path_address;
        pursuit_data->pending = 0;
        pursuit_data->timer = g_frame_time * 2.0f;
        chomper_moby->flags &= ~0x1000;
        *(u128 *)scratch = *(u128 *)(hit + 0x10);
        HeadingFromVector(scratch, scratch + 4, &pursuit_data->jump_speed, &pursuit_data->turn_speed);
        InitKnockback(chomper_moby, pursuit_data->knock, 5, 1, 0, scratch[4]);
        pursuit_data->f170 = 8.0f;
        pursuit_data->f174 = 16.0f;
        chomper_moby->state = 8;
        chomper_moby->i94 = 0;
        pursuit_data->reaction_time = 0x78;
        RerollEffectCounter(chomper_moby, pursuit_data->reaction);
    }
    chomper_moby->bA4 = 0xFF;
    StepColorFade(chomper_moby, pursuit_data->reaction);
    reaction_flags_or_path_entry_address = (int)&kalebo3_path_table[pursuit_data->path];
    reaction_kind_or_path_address = *(int *)reaction_flags_or_path_entry_address;
    if (FindNearestEligibleMoby(chomper_moby, pursuit_data->target, 16.0f, 0, 0, (void *)(reaction_kind_or_path_address + 0x10), *(int *)reaction_kind_or_path_address) != 2) {
        if (vec_distance_xy(pursuit_data->home, pursuit_data->target) > 16.0f ||
            FastAbsF(chomper_moby->position[2] - pursuit_data->target[2]) > 3.0f) {
            pursuit_data->i1C4 = 2;
        }
    }
    if (pursuit_data->i1C0 == 0) {
        struct Hero *player = (struct Hero *)(hero_globals_base + 0xE1D);
        pursuit_data->i1C0 = (int)player->moby;
        qcopy(pursuit_data->target, &player->motion.pos);
    }
}
extern float SteerAngleWithVelocity(float *, float *, float, float, float, float);
extern float ApproachWithVelocity_r(float *, float, float, float, float, float *) __asm__("func_00214D88");
extern void move_4318(void *, void *, float, float, float, int);
extern void resolve_point_path_segment_xy_clearance(float, void *, void *, void *);

/* Steers and moves a moby toward a target point, returning the distance. */
float move_chomper_toward_position(void *m_v, void *t_v) {
    char *m = m_v;
    float *t = t_v;
    char *d = ((char *)((Moby *)m)->pvars);
    float vel;
    float vec[4];
    float dist;
    float oldz;
    float a = fast_atan2(t[0] - ((Moby *)m)->pos.x, t[1] - ((Moby *)m)->pos.y);
    a = FastAddRots(a, *(float *)(d + 0x1F8));
    oldz = ((Moby *)m)->pos.z;
    vel = 0.0f;
    dist = FastVecDist(m + 0x10, t);
    SteerAngleWithVelocity((float *)(m + 0x48), (float *)(d + 0x1F4), a,
                         g_frame_time_sq * 12.566371f, g_frame_time_sq * 12.566371f,
                         g_frame_time * 12.566371f);
    ApproachWithVelocity_r(&vel, dist,
                   g_frame_time_sq * 8.0f, g_frame_time_sq * 12.0f,
                   g_frame_time * 4.0f, (float *)(d + 0x204));
    vec_scale_to_length(vec, m + 0xC0, *(float *)(d + 0x204));
    vec[2] = *(float *)(d + 0x208) - g_frame_time_sq * 10.0f;
    move_4318(m, vec, 0.5f, 0.5f, 0.0f, 0x10);
    resolve_point_path_segment_xy_clearance(0.333f, *(void **)(d + 0x1F0), m + 0x10, m + 0x10);
    *(float *)(d + 0x208) = oldz - ((Moby *)m)->pos.z;
    return dist;
}
